from pathlib import Path
ROOT=Path('manuscript/ga1')

def rep(fn,old,new):
    p=ROOT/fn
    t=p.read_text(encoding='utf-8')
    n=t.count(old)
    if n!=1: raise SystemExit(f'{fn}: expected block once, got {n}: {old[:90]!r}')
    p.write_text(t.replace(old,new,1),encoding='utf-8')

